const raw = $input.first().json;
const body = raw.body || raw;

const email = body.email || body.toEmail || raw.email;
const subject = body.subject || raw.subject || 'InsightHub - Search Results';
const agentName = body.agentName || raw.agentName || 'AI Agent';
const results = body.results || raw.results || [];

let tableHeaders = '';
let tableRows = '';

if (Array.isArray(results) && results.length > 0) {
  const keys = Object.keys(results[0]);
  tableHeaders = keys.map(k => `<th style="padding:12px 14px;text-align:left;background:#0066FF;color:white;font-size:12px;font-weight:bold;text-transform:uppercase;letter-spacing:0.5px;">${k}</th>`).join('');

  tableRows = results.map((row, idx) => {
    const bg = idx % 2 === 0 ? '#ffffff' : '#f8fafc';
    const cells = keys.map(k => {
      let val = row[k] != null ? String(row[k]) : '';
      val = val.replace(/\n/g, '<br/>');
      return `<td style="padding:10px 14px;border-bottom:1px solid #e2e8f0;font-size:13px;color:#1e293b;line-height:1.5;">${val}</td>`;
    }).join('');
    return `<tr style="background:${bg};">${cells}</tr>`;
  }).join('');
}

const htmlBody = body.htmlBody || `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family:'Segoe UI',Arial,sans-serif;background:#f1f5f9;padding:20px 10px;">
  <div style="max-width:960px;margin:0 auto;background:white;border-radius:12px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);border:1px solid #e2e8f0;">
    <div style="background:linear-gradient(135deg,#0066FF 0%,#10b981 100%);padding:28px 36px;">
      <h1 style="color:white;margin:0;font-size:24px;">InsightHub</h1>
      <p style="color:rgba(255,255,255,0.9);margin:6px 0 0;font-size:14px;">Sri Lanka Telecom Mobitel - AI Sales Intelligence</p>
    </div>
    <div style="padding:28px 36px;">
      <h2 style="color:#0f172a;margin:0 0 6px;font-size:20px;">${agentName} Results</h2>
      <p style="color:#64748b;margin:0 0 20px;font-size:13px;">Generated on ${new Date().toLocaleString()} • ${results.length} records</p>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;">
          <thead><tr>${tableHeaders}</tr></thead>
          <tbody>${tableRows}</tbody>
        </table>
      </div>
    </div>
    <div style="background:#f8fafc;padding:18px 36px;text-align:center;border-top:1px solid #e2e8f0;">
      <p style="color:#94a3b8;font-size:12px;margin:0;">This email was automatically generated by InsightHub AI. &copy; ${new Date().getFullYear()} Mobitel</p>
    </div>
  </div>
</body>
</html>
`;

return [{ json: { email, toEmail: email, subject, htmlBody } }];
